"""Generated by Murakumo. Do not edit: change the model, then run `murakumo generate`.

The runtime the model modules call: it reads the raw tables, builds each model from its SQL (the
same SQL as the dbt project), keeps incremental, cumulative and snapshot tables up to date
between runs, runs the tests, and records every run in the audit tables.

Engines:
- pyspark: Spark SQL over temporary views; tables are written as Parquet (or Delta).
- polars:  Polars data frames, with each model's SQL run by DuckDB over them; tables are written
           as Parquet.

Tables go to <output>/<schema>/<table>/ (Spark) or <output>/<schema>/<table>.parquet (Polars), and
the audit tables to <output>/audit/. Views are kept in memory for the run.
"""

from __future__ import annotations

import json
import os
import shutil
import time
import uuid
from datetime import UTC, datetime
from pathlib import Path

CONFIG = json.loads((Path(__file__).parent / "project.json").read_text(encoding="utf-8"))
RUN_DATE = "__MURAKUMO_RUN_DATE__"


class Context:
    def __init__(
        self,
        engine: str,
        output: Path,
        duckdb_path: str | None = None,
        data: dict[str, str] | None = None,
        run_date: str | None = None,
        schedule: str | None = None,
        table_format: str = "parquet",
    ):
        self.engine = engine
        self.output = Path(output)
        self.output.mkdir(parents=True, exist_ok=True)
        self.duckdb_path = duckdb_path
        self.data = {k.lower(): v for k, v in (data or {}).items()}
        self.run_date = run_date or ""
        self.schedule = schedule or ""
        self.format = table_format
        self.run_id = uuid.uuid4().hex[:12]
        self.started = datetime.now(UTC).replace(tzinfo=None)
        self.models: list[dict] = []
        self.tests: list[dict] = []
        self.loads: list[dict] = []
        self.built: set[str] = set()
        if engine == "pyspark":
            self._start_spark()
        else:
            import duckdb

            self.con = duckdb.connect()

    # engine -------------------------------------------------------------------------------------

    def _start_spark(self) -> None:
        if not os.environ.get("JAVA_HOME"):
            try:  # `pip install jdk4py` brings a Java runtime with it
                import jdk4py

                os.environ["JAVA_HOME"] = str(jdk4py.JAVA_HOME)
            except ImportError:
                pass
        from pyspark.sql import SparkSession

        builder = (
            SparkSession.builder.master(os.environ.get("MURAKUMO_SPARK_MASTER", "local[*]"))
            .appName(f"murakumo-{CONFIG['project']}")
            .config("spark.ui.enabled", "false")
            .config("spark.sql.session.timeZone", "UTC")
            .config("spark.sql.shuffle.partitions", os.environ.get("MURAKUMO_SPARK_PARTITIONS", "4"))
        )
        if self.format == "delta":
            from delta import configure_spark_with_delta_pip

            builder = builder.config("spark.sql.extensions", "io.delta.sql.DeltaSparkSessionExtension").config(
                "spark.sql.catalog.spark_catalog", "org.apache.spark.sql.delta.catalog.DeltaCatalog"
            )
            builder = configure_spark_with_delta_pip(builder)
        self.spark = builder.getOrCreate()
        self.spark.sparkContext.setLogLevel("ERROR")

    def sql(self, query: str):
        query = query.replace(RUN_DATE, self.run_date)
        if self.engine == "pyspark":
            return self.spark.sql(query)
        return self.con.sql(query).pl()

    def register(self, view: str, frame) -> None:
        if self.engine == "pyspark":
            frame.createOrReplaceTempView(view)
        else:
            self.con.register(view, frame)

    def rows(self, frame) -> int:
        return frame.count() if self.engine == "pyspark" else frame.height

    # storage ------------------------------------------------------------------------------------

    def path(self, schema: str, name: str) -> Path:
        base = self.output / schema / name
        return base if self.engine == "pyspark" else base.with_suffix(".parquet")

    def exists(self, schema: str, name: str) -> bool:
        return self.path(schema, name).exists()

    def read(self, schema: str, name: str):
        path = str(self.path(schema, name))
        if self.engine == "pyspark":
            reader = self.spark.read.format("delta") if self.format == "delta" else self.spark.read
            return reader.load(path) if self.format == "delta" else reader.parquet(path)
        import polars as pl

        return pl.read_parquet(path)

    def write(self, schema: str, name: str, frame):
        """Replace a table. Written beside it first, so a table read to build itself is never lost."""
        path = self.path(schema, name)
        path.parent.mkdir(parents=True, exist_ok=True)
        staged = path.with_name(path.name + ".new")
        shutil.rmtree(staged, ignore_errors=True) if staged.is_dir() else staged.unlink(missing_ok=True)
        if self.engine == "pyspark":
            writer = frame.write.mode("overwrite")
            (writer.format("delta").save(str(staged)) if self.format == "delta" else writer.parquet(str(staged)))
        else:
            frame.write_parquet(staged)
        if path.is_dir():
            shutil.rmtree(path)
        elif path.exists():
            path.unlink()
        staged.rename(path)
        return self.read(schema, name)

    # loading ------------------------------------------------------------------------------------

    def load_raw(self) -> None:
        """Every raw table: from --data files, else from the DuckDB file's raw schemas."""
        for table in CONFIG["raw"]:
            location = self.data.get(table["table"].lower()) or self.data.get(
                f"{table['source']}.{table['table']}".lower()
            )
            if location:
                frame = self._read_file(location)
            elif self.duckdb_path:
                frame = self._read_duckdb(table["schema"], table["table"])
            else:
                raise SystemExit(f"no data for raw table {table['table']}: pass --duckdb or --data")
            frame = self._landing(frame, table)
            self.register(table["view"], frame)
            self.loads.append(
                {"source": table["source"], "table_name": table["table"], "rows_ingested": self.rows(frame)}
            )

    def _landing(self, frame, table: dict):
        """The raw columns, with the landing columns ingestion writes, as the warehouse has them."""
        names = [c for c in table["columns"]]
        if self.engine == "pyspark":
            from pyspark.sql import functions as F

            present = set(frame.columns)
            for column in ("_ingested_at", "_batch_id"):
                if column not in present:
                    value = F.current_timestamp() if column == "_ingested_at" else F.lit(self.run_id)
                    frame = frame.withColumn(column, value)
            return frame.select(*names, "_ingested_at", "_batch_id")
        import polars as pl

        if "_ingested_at" not in frame.columns:
            frame = frame.with_columns(pl.lit(datetime.now()).alias("_ingested_at"))
        if "_batch_id" not in frame.columns:
            frame = frame.with_columns(pl.lit(self.run_id).alias("_batch_id"))
        return frame.select([*names, "_ingested_at", "_batch_id"])

    def _read_file(self, location: str):
        suffix = location.lower().rsplit(".", 1)[-1]
        if self.engine == "pyspark":
            reader = self.spark.read
            if suffix == "csv":
                return reader.option("header", True).option("inferSchema", True).csv(location)
            return reader.json(location) if suffix == "json" else reader.parquet(location)
        import polars as pl

        if suffix == "csv":
            return pl.read_csv(location, try_parse_dates=True)
        return pl.read_json(location) if suffix == "json" else pl.read_parquet(location)

    def _read_duckdb(self, schema: str, table: str):
        import duckdb

        with duckdb.connect(self.duckdb_path, read_only=True) as con:
            relation = con.sql(f'select * from "{schema}"."{table}"')
            if self.engine != "pyspark":
                return relation.pl()
            # Spark reads the table as Parquet, which keeps every type (time zones included) as it is.
            staged = self.output / "_landing" / schema / f"{table}.parquet"
            staged.parent.mkdir(parents=True, exist_ok=True)
            relation.write_parquet(str(staged))
        return self.spark.read.parquet(str(staged))

    # models -------------------------------------------------------------------------------------

    def _timed(self, name: str, kind: str, action) -> None:
        started = time.time()
        try:
            frame = action()
            status, rows, message = "success", (self.rows(frame) if frame is not None else None), None
        except Exception as exc:  # noqa: BLE001 - recorded, then raised
            status, rows, message = "error", None, " ".join(str(exc).split())[:1000]
            self.models.append(
                {"model": name, "kind": kind, "status": status, "rows_in_table": rows,
                 "seconds": round(time.time() - started, 3), "message": message}
            )  # fmt: skip
            raise
        self.models.append(
            {"model": name, "kind": kind, "status": status, "rows_in_table": rows,
             "seconds": round(time.time() - started, 3), "message": message}
        )  # fmt: skip
        self.built.add(name)

    def view(self, name: str, schema: str, view: str, query: str) -> None:
        """Views are built in memory for the run, as the warehouse would read them."""
        self.register(view, self.sql(query))
        self.built.add(name)

    def table(self, name: str, schema: str, view: str, query: str) -> None:
        def build():
            frame = self.write(schema, name, self.sql(query))
            self.register(view, frame)
            return frame

        self._timed(name, "model", build)

    def existing(self, name: str, schema: str, view: str) -> None:
        """A table another schedule builds: read it as it was last written."""
        if self.exists(schema, name):
            self.register(view, self.read(schema, name))
            return True
        return False

    def incremental(self, name: str, schema: str, view: str, full: str, new_rows: str, keys: list[str]) -> None:
        """Built in full the first time; then the new rows replace those with the same key."""

        def build():
            if not self.exists(schema, name):
                frame = self.write(schema, name, self.sql(full))
            else:
                self.register(view, self.read(schema, name))  # `this`, for the new rows' query
                self.register("murakumo__new_rows", self.sql(new_rows))
                match = " and ".join(f"n.{k} = t.{k}" for k in keys) if keys else "false"
                kept = f"select t.* from {view} t where not exists (select 1 from murakumo__new_rows n where {match})"
                columns = ", ".join(self.columns(view))
                merged = self.sql(f"select {columns} from ({kept}) union all select {columns} from murakumo__new_rows")
                frame = self.write(schema, name, merged)
            self.register(view, frame)
            return frame

        self._timed(name, "model", build)

    def columns(self, view: str) -> list[str]:
        frame = self.sql(f"select * from {view} limit 0")
        return [self.q(c) for c in frame.columns]

    def q(self, name: str) -> str:
        """A column name as the engine's SQL needs it written."""
        if name.isidentifier() and name == name.lower():
            return name
        return f"`{name}`" if self.engine == "pyspark" else '"' + name.replace('"', '""') + '"'

    def snapshot(self, name: str, schema: str, view: str, source: str, keys: list[str], columns: list[str]) -> None:
        """SCD2 history as dbt's check strategy keeps it: close changed rows, add their new versions."""

        def build():
            now = "cast(current_timestamp as timestamp)"
            listed = ", ".join(columns)
            if not self.exists(schema, name):
                query = (
                    f"select {listed}, {now} as dbt_valid_from, cast(null as timestamp) as dbt_valid_to from {source}"
                )
            else:
                self.register(view, self.read(schema, name))
                key = " and ".join(f"v.{k} = s.{k}" for k in keys)
                changed = " or ".join(f"v.{c} is distinct from s.{c}" for c in columns if c not in keys) or "false"
                closing = (
                    f"case when s.dbt_valid_to is null and exists "
                    f"(select 1 from {source} v where {key} and ({changed})) then {now} else s.dbt_valid_to end"
                )
                current = f"select 1 from {view} s where {key} and s.dbt_valid_to is null and not ({changed})"
                query = (
                    f"select {', '.join('s.' + c for c in columns)}, s.dbt_valid_from, {closing} as dbt_valid_to "
                    f"from {view} s union all "
                    f"select {', '.join('v.' + c for c in columns)}, {now}, cast(null as timestamp) "
                    f"from {source} v where not exists ({current})"
                )
            frame = self.write(schema, name, self.sql(query))
            self.register(view, frame)
            return frame

        self._timed(name, "snapshot", build)

    # tests and the run log ----------------------------------------------------------------------

    def test(self, model: str, name: str, column: str | None, query: str, severity: str) -> None:
        if model not in self.built:
            return
        failures = self.rows(self.sql(query))
        status = "pass" if failures == 0 else ("warn" if severity == "warn" else "fail")
        self.tests.append(
            {"test": name, "model": model, "column_name": column, "status": status, "failures": failures,
             "severity": severity}
        )  # fmt: skip

    def finish(self) -> dict:
        """Append this run to the audit tables, and return a summary."""
        import polars as pl

        finished = datetime.now(UTC).replace(tzinfo=None)
        failed_models = sum(m["status"] != "success" for m in self.models)
        failed_tests = sum(t["status"] == "fail" for t in self.tests)
        run_log = [{
            "run_id": self.run_id, "engine": self.engine, "environment": "python", "schedule": self.schedule,
            "invoked_by": os.environ.get("MURAKUMO_INVOKED_BY", os.environ.get("USER", "")),
            "started_at": self.started, "finished_at": finished,
            "status": "failed" if failed_models or failed_tests else "success",
            "models_ok": len(self.models) - failed_models, "models_failed": failed_models,
            "tests_passed": len(self.tests) - failed_tests, "tests_failed": failed_tests,
        }]  # fmt: skip
        stamp = {"run_id": self.run_id, "finished_at": finished}
        tables = {
            "run_log": run_log,
            "model_runs": [{**stamp, **m} for m in self.models],
            "dq_results": [{**stamp, **t} for t in self.tests],
            "row_counts": [
                {
                    "run_id": self.run_id,
                    **load,
                    "batch_id": self.run_id,
                    "rows_rejected": 0,
                    "reason": None,
                    "loaded_at": finished,
                }
                for load in self.loads
            ],  # fmt: skip
        }
        audit = self.output / "audit"
        audit.mkdir(parents=True, exist_ok=True)
        for name, rows in tables.items():
            if not rows:
                continue
            frame = pl.DataFrame(rows, infer_schema_length=None)
            path = audit / f"{name}.parquet"
            if path.exists():
                frame = pl.concat([pl.read_parquet(path), frame], how="diagonal_relaxed")
            frame.write_parquet(path)
        if self.engine == "pyspark":
            self.spark.stop()
        return run_log[0]
